import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.C8822HRV.js";const m=JSON.parse('{"title":"Change packs and product memory","description":"How sdd separates PR-scoped change packs from durable product memory — discovery vs delivery packs, greenfield promote, and constitution.","frontmatter":{"title":"Change packs and product memory","description":"How sdd separates PR-scoped change packs from durable product memory — discovery vs delivery packs, greenfield promote, and constitution.","head":[["meta",{"property":"og:title","content":"Change packs and product memory · sdd"}],["meta",{"property":"og:description","content":"How sdd separates PR-scoped change packs from durable product memory — discovery vs delivery packs, greenfield promote, and constitution."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/concepts/change-packs/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"Change packs and product memory · sdd"}],["meta",{"name":"twitter:description","content":"How sdd separates PR-scoped change packs from durable product memory — discovery vs delivery packs, greenfield promote, and constitution."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/concepts/change-packs/"}]]},"headers":[],"relativePath":"concepts/change-packs.md","filePath":"concepts/change-packs.md","lastUpdated":1785895617000}'),n={name:"concepts/change-packs.md"};function r(d,e,i,c,p,l){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="change-packs-and-memory" tabindex="-1">Change packs and memory <a class="header-anchor" href="#change-packs-and-memory" aria-label="Permalink to &quot;Change packs and memory&quot;">​</a></h1><p>Long wikis get ignored. Chat disappears. Reviews need something in the middle.</p><p><strong><code>sdd</code> keeps two kinds of notes:</strong></p><ol><li><strong>Change pack</strong> — for <em>this</em> task or PR (short-lived, easy to review)</li><li><strong>Memory</strong> — for product truths that should last (keep it short)</li></ol><p>After work finishes, copy lasting rules into <code>memory/constitution.md</code> when they truly matter. The refine command never rewrites constitution for you.</p><p><strong>Pack = this work. Memory = product law.</strong></p><h3 id="why-markdown-not-a-binary-store" tabindex="-1">Why markdown (not a binary store)? <a class="header-anchor" href="#why-markdown-not-a-binary-store" aria-label="Permalink to &quot;Why markdown (not a binary store)?&quot;">​</a></h3><p>Specs can look long, but <strong>git markdown is the right default</strong>:</p><ul><li>Reviewable in PRs next to code</li><li>Works offline with any editor</li><li>Agents and humans share the same files</li><li>No second database to sync</li></ul><p>Save <strong>tokens on product source code</strong> with <code>sdd context</code> (local AST) or <strong>external MCP sources</strong> (<a href="./../guides/mcp">guide</a>), not by inventing a private format for intent/design.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>memory/index.md            ← map (stable)</span></span>
<span class="line"><span>memory/constitution.md</span></span>
<span class="line"><span>memory/product.md          ← after greenfield (from vision)</span></span>
<span class="line"><span>memory/requirements.md     ← after greenfield</span></span>
<span class="line"><span>memory/features.md         ← product backlog; sdd backlog start F-001</span></span>
<span class="line"><span>memory/architecture.md</span></span>
<span class="line"><span>changes/&lt;id&gt;/              ← this PR’s specs + meta.yaml</span></span>
<span class="line"><span>.sdd/protocol.md           ← process rules for agents</span></span>
<span class="line"><span>.sdd/active-context.md</span></span></code></pre></div><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Packs</strong></td><td>Every change via <code>sdd new</code> or <code>sdd greenfield</code> / <code>sdd backlog start</code></td></tr><tr><td><strong>Memory</strong></td><td>Durable truths only — promote after complete (greenfield auto-promotes product spine)</td></tr><tr><td><strong>Shared trail</strong></td><td>Agents and humans read the same files for <em>this</em> change</td></tr></tbody></table><h2 id="two-kinds-of-packs" tabindex="-1">Two kinds of packs <a class="header-anchor" href="#two-kinds-of-packs" aria-label="Permalink to &quot;Two kinds of packs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>How it starts</th><th>What it produces</th></tr></thead><tbody><tr><td><strong>Discovery (greenfield)</strong></td><td><code>sdd greenfield &quot;idea&quot;</code></td><td>Vision, requirements, <code>F-NNN</code> backlog, architecture → promoted into <code>memory/</code> on complete</td></tr><tr><td><strong>Delivery (feature / hotfix / …)</strong></td><td><code>sdd new &quot;…&quot;</code> or <code>sdd backlog start F-001</code></td><td>Specs + code for one PR-sized slice</td></tr></tbody></table><p>Greenfield does <strong>not</strong> implement the whole product in one pack. It writes the product spine; each backlog row becomes its own delivery pack.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../guides/greenfield">Greenfield guide</a></li><li><a href="./../tutorials/first-change">First change tutorial</a></li><li><a href="./../guides/refine">Refine</a></li></ul>`,18)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
